@startuml

class Airline {
  + ID
  + name
}

class Flight {
  + ID
  + departure_time
  + arrival_time
}

class Airport {
  + ID
  + name
}

class Aircraft {
  + name
  + working_state
  + landed
}

class AircraftType {
  + name
}

class Pilot {
  + name
  + experience_level
}

class Captain extends Pilot {}
class CoPilot extends Pilot {}
class Navigator extends Pilot {}

Airline "1" -- "*" Flight : operates
Airline "1" -- "*" Aircraft : owns
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives at
Flight "*" -- "1" Aircraft : uses
Flight "1" -- "1" Captain : has
Flight "1" -- "1" CoPilot : has
Aircraft "*" -- "1" AircraftType : is of
AircraftType "1" -- "1..* Captain" Pilot
AircraftType "1" -- "1..* CoPilot" Pilot
AircraftType "1" -- "0..* Navigator" Pilot

@enduml

